# prompt user to input two integers
num1 = input("Enter the first integer: ")
num2 = input("Enter the second integer: ")

# check if both inputs are valid integers and not negative numbers
if num1.isdigit() and num2.isdigit():
    num1 = int(num1)
    num2 = int(num2)
    if num1 < 0 or num2 < 0:
        print("Please enter positive integers only.")
    else:
        # define a function to check for common factors
        def gcd(a, b):
            while b != 0:
                t = b
                b = a % b
                a = t
            return a

        # check if the greatest common divisor is 1
        if gcd(num1, num2) == 1:
            print(f"{num1} and {num2} are relatively prime.")
        else:
            print(f"{num1} and {num2} are not relatively prime.")
else:
    print("Please enter valid integers only.")
